import { SignJWT } from 'jose';

const secret = new TextEncoder().encode(process.env.OPEND_EMBED_SECRET);
const DOCS_URL = 'https://docs.example.com'; // the docs site's PUBLIC_URL, no trailing slash

export function opendToken(user) {
  return new SignJWT({ email: user.email, org: user.opendOrg })
    .setProtectedHeader({ alg: 'HS256' })
    .setAudience(DOCS_URL)
    .setIssuedAt()
    .setExpirationTime('5m')
    .sign(secret);
}

// Express, for example. Only for signed-in users, and never cached.
app.get('/api/opend-token', requireSignIn, async (req, res) => {
  res.set('cache-control', 'no-store').type('text/plain').send(await opendToken(req.user));
});

import { createHmac } from 'node:crypto';

export function opendToken({ email, org }) {
  const b64 = (value) => Buffer.from(JSON.stringify(value)).toString('base64url');
  const now = Math.floor(Date.now() / 1000);
  const body = `${b64({ alg: 'HS256', typ: 'JWT' })}.${b64({ email, org, aud: DOCS_URL, iat: now, exp: now + 300 })}`;
  const signature = createHmac('sha256', process.env.OPEND_EMBED_SECRET).update(body).digest('base64url');
  return `${body}.${signature}`;
}
